class MyFilter : ICustomFilter
{
	public bool IsMatching(StorableObject obj)
	{
		Function f = obj as Function;
		if (f != null)
		{
			return (f.IsMainFunction && f.SubFunctions.Length != 0);
		}
		return false;
	}
}

