member.example:
UndoStep usage - only inside "using".

using (UndoStep undo = new UndoManager().CreateUndoStep())
{
	using(Transaction txn = new TransactionManager().CreateTransaction())
	{
		Function f;
		f.Name = "F1";
		txn.Commit();
	}
    undo.DoUndo();
}

UndoStep usage - only inside "using".

using (UndoStep undo = new UndoManager().CreateUndoStep())
{
	SelectionSet oSS = new SelectionSet();
	Function f = oSS.Selection[0] as Function;
	f.Properties.FUNC_CUSTOM_SUPPLEMENTARYFIELD01 = "new value";
	// ... code ...				//
    // and if needed DoUndo call//
    undo.DoUndo();
}

Transaction manager usage example.

using (Transaction txn = new TransactionManager().CreateTransaction())
{
Function f;
f.Name = "F1";			
txn.Commit();
}

Store() usage example. In this example Function f Name is set
"F1", Description is set "generic function". The changes are
stored in the project. Name "F2" is not committed, so it is
not stored.
using (Transaction txn = new TransactionManager().CreateTransaction())
{
    Function f;
    f.Name = "F1";
    f.Description = "generic function";
    txn.Store();
    f.Name = "F2";
    txn.Abort();
}

Transaction usage - only inside "using".

using (Transaction txn = new TransactionManager().CreateTransaction())
{
    Function f;
    f.Name = "F1";
    txn.Commit();
}

